+"use node";
+
+// import stripe stuff
+import Stripe from "stripe";
+
+// import convex stuff
+import { v } from "convex/values";
+import { action, internalAction } from "./_generated/server";
+import { internal } from "./_generated/api";
+import { getSubscriptionPeriodEnd, getInvoiceSubscription } from './stripe-subscription-period';
+
+const url = process.env.NEXT_PUBLIC_APP_URL;
+const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!, {
+  apiVersion: "2026-09-30.endive",
+});
+
+export const portal = action({
+  args: { userId: v.string() },
+  handler: async (ctx, args) => {
+    const identity = await ctx.auth.getUserIdentity();
+
+    if (!identity) {
+      throw new Error("Unauthorized user");
+    }
+
+    if (!args.userId) {
+      throw new Error("No user ID provided");
+    }
+
+    const userSubscription = await ctx.runQuery(internal.subscriptions.get, {
+      userId: args.userId,
+    });
+
+    if (!userSubscription) {
+      throw new Error("No subscription found");
+    }
+
+    const session = await stripe.billingPortal.sessions.create({
+      customer: userSubscription.stripeCustomerId,
+      return_url: url,
+    });
+
+    return session.url!;
+  },
+});
+
+export const pay = action({
+  args: { userId: v.string() },
+  handler: async (ctx, args) => {
+    const identity = await ctx.auth.getUserIdentity();
+
+    if (!identity) {
+      throw new Error("You must be logged in to make a payment");
+    }
+
+    if (!args.userId) {
+      throw new Error("User ID is required");
+    }
+
+    const session = await stripe.checkout.sessions.create({
+      success_url: url,
+      cancel_url: url,
+      customer_email: identity.email,
+      line_items: [
+        {
+          price_data: {
+            currency: "USD",
+            product_data: {
+              name: "Pro",
+              description: "Pro Plan",
+            },
+            unit_amount: 1000,
+            recurring: {
+              interval: "month",
+            },
+          },
+          quantity: 1,
+        },
+      ],
+      metadata: {
+        userId: args.userId,
+      },
+      mode: "subscription",
+    });
+
+    return session.url!;
+  },
+});
+
+export const fulfill = internalAction({
+  args: { signature: v.string(), payload: v.string() },
+  handler: async (ctx, { signature, payload }) => {
+    const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET as string;
+
+    try {
+      const event = stripe.webhooks.constructEvent(
+        payload,
+        signature,
+        webhookSecret
+      );
+
+      const session = event.data.object as Stripe.Checkout.Session;
+
+      if (event.type === "checkout.session.completed") {
+        const subscription = await stripe.subscriptions.retrieve(
+          session.subscription as string
+        );
+
+        if (!session?.metadata?.userId) {
+          throw new Error("New user ID");
+        }
+
+        await ctx.runMutation(internal.subscriptions.create, {
+          userId: session.metadata.userId as string,
+          stripeSubscriptionId: subscription.id as string,
+          stripeCustomerId: subscription.customer as string,
+          stripePriceId: subscription.items.data[0].price.id as string,
+          stripeCurrentPeriodEnd: (getSubscriptionPeriodEnd(subscription, (items) => items[0])) * 1000,
+        });
+      }
+
+      if (event.type === "invoice.payment_succeeded") {
+        const subscription = await stripe.subscriptions.retrieve(
+          (getInvoiceSubscription(session)) as string
+        );
+
+        await ctx.runMutation(internal.subscriptions.update, {
+          stripeSubscriptionId: subscription.id as string,
+          stripeCurrentPeriodEnd: (getSubscriptionPeriodEnd(subscription, (items) => items[0])) * 1000,
+        });
+      }
+      return { success: true };
+    } catch (err) {
+      console.error(err);
+      return { success: false };
+    }
+  },
+});
